const raw = $input.first().json;
const body = raw.body || raw;
const graphToken = '{{META_GRAPH_ACCESS_TOKEN}}';

function pick(obj, ...keys) {
  for (const k of keys) {
    if (obj && obj[k] != null && String(obj[k]).trim() !== '') return String(obj[k]).trim();
  }
  return '';
}

function mapFieldData(rows, target) {
  for (const row of (rows || [])) {
    const n = (row.name || '').toLowerCase();
    const v = (row.values && row.values[0]) || '';
    if (!v) continue;
    if (n.includes('first') || n === 'prénom' || n === 'prenom') target.first_name = target.first_name || v;
    else if (n.includes('last') || n === 'nom' || n === 'name') target.last_name = target.last_name || v;
    else if (n.includes('phone') || n.includes('téléphone') || n.includes('tel') || n.includes('mobile')) target.phone = target.phone || v;
    else if (n.includes('email') || n.includes('courriel')) target.email = target.email || v;
    else if (n.includes('city') || n.includes('ville')) target.city = target.city || v;
    else if (n.includes('address') || n.includes('adresse') || n.includes('street')) target.full_address = target.full_address || v;
    else if (n.includes('chauffage') || n.includes('heating')) target.chauffage_actuel = target.chauffage_actuel || v;
    else if (n.includes('budget')) target.budget_range = target.budget_range || v;
    else if (n.includes('project') || n.includes('projet')) target.project_type = target.project_type || v;
  }
}

let page_id = pick(body, 'page_id', 'facebook_page_id');
let form_id = pick(body, 'form_id', 'leadgen_form_id');
let leadgen_id = pick(body, 'leadgen_id', 'meta_lead_id', 'id');
const field_data = {};

if (body.entry && Array.isArray(body.entry)) {
  for (const entry of body.entry) {
    for (const ch of (entry.changes || [])) {
      if (ch.field === 'leadgen' && ch.value) {
        page_id = page_id || String(ch.value.page_id || '');
        form_id = form_id || String(ch.value.form_id || '');
        leadgen_id = leadgen_id || String(ch.value.leadgen_id || '');
      }
    }
  }
}

if (body.data && typeof body.data === 'object' && !Array.isArray(body.data)) {
  const d = body.data;
  const full = pick(d, 'full_name', 'nom_complet');
  const parts = full.split(/\s+/).filter(Boolean);
  field_data.first_name = pick(d, 'first_name', 'prénom', 'prenom') || parts[0] || '';
  field_data.last_name = pick(d, 'last_name', 'nom') || parts.slice(1).join(' ') || '';
  field_data.phone = pick(d, 'phone_number', 'phone', 'mobile', 'tel');
  field_data.email = pick(d, 'email', 'courriel');
  field_data.full_address = pick(d, 'street_address', 'address', 'full_address', 'adresse');
  field_data.city = pick(d, 'city', 'ville');
  field_data.chauffage_actuel = pick(d, 'chauffage_actuel', 'current_heating');
  form_id = form_id || (body.form && body.form.id) || '';
  page_id = page_id || (body.page && body.page.id) || '';
  leadgen_id = leadgen_id || body.id || '';
}

mapFieldData(body.field_data, field_data);

if (leadgen_id && graphToken && !pick(field_data, 'phone', 'phone_number', 'mobile')) {
  try {
    const g = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://graph.facebook.com/v21.0/${leadgen_id}`,
      qs: { access_token: graphToken, fields: 'field_data,created_time,id' },
      json: true,
    });
    mapFieldData(g.field_data, field_data);
  } catch (e) {
    field_data._graph_fetch_error = String(e.message || e);
  }
}

const payload = {
  ...body,
  ...field_data,
  page_id,
  facebook_page_id: page_id,
  form_id,
  leadgen_form_id: form_id,
  meta_lead_id: leadgen_id,
  leadgen_id,
};

return [{ json: payload }];

const p = $('Parser leadgen Meta').first().json;
const token = '{{META_LEADS_ROUTING_TOKEN}}';
let route = {};
try {
  route = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://intellixcrm.com/api/meta/leads/resolve',
    headers: {
      'Content-Type': 'application/json',
      'X-Meta-Leads-Token': token,
    },
    body: p,
    json: true,
  });
} catch (e) {
  route = {
    status: 'error',
    pipeline: 'unknown',
    skip_orchestrator: true,
    message: String(e.message || e),
  };
}
return [{ json: { ...p, _route: route } }];

const p = $input.first().json;
const token = '{{MARKETING_META_WEBHOOK_TOKEN}}';
let res = {};
try {
  res = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://intellixcrm.com/api/marketing/meta-lead',
    headers: {
      'Content-Type': 'application/json',
      'X-Marketing-Meta-Webhook-Token': token,
    },
    body: {
      first_name: p.first_name,
      last_name: p.last_name,
      phone: p.phone,
      email: p.email,
      city: p.city,
      full_address: p.full_address,
      page_id: p.page_id,
      form_id: p.form_id,
      meta_lead_id: p.meta_lead_id || p.leadgen_id || '',
      assign_user_login: p._route.assign_user_login || '',
    },
    json: true,
  });
} catch (e) {
  res = { status: 'error', message: String(e.message || e) };
}
return [{ json: { ...p, _odoo: res } }];
